from pathlib import Path
import json
from PIL import Image,ImageDraw
P=Path(__file__).resolve().parent; data={g:json.loads((P/f'{g}-manifest.json').read_text())['states'] for g in ('bare','helmet')}
frames=[];durations=[];elapsed=0;prior=0
for slot,time in enumerate(data['bare'][0]['frameDurationsMs']):
 board=Image.new('RGB',(512,280),'#202a30');d=ImageDraw.Draw(board)
 for col,gear in enumerate(('bare','helmet')):
  im=Image.open(P/data[gear][0]['frameFiles'][slot]).convert('RGBA');board.paste(im,(col*256,15),im);d.text((col*256+5,2),gear+' / '+str(slot),fill='white')
 elapsed+=time*3;end=round(elapsed/10)*10;durations.append(end-prior);prior=end;frames.append(board)
frames[0].save(P/'read-cycle.gif',save_all=True,append_images=frames[1:],duration=durations,loop=0,disposal=2)
with Image.open(P/'read-cycle.gif') as gif:
 total=0
 for slot in range(gif.n_frames):gif.seek(slot);total+=gif.info['duration']
 assert total==36000
page='''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Veld coherent sofa reading</title><style>body{background:#202a30;color:#e1e7eb;font:16px system-ui;margin:24px}p{max-width:80ch;line-height:1.5}a{color:#8cc6e7}.row{display:flex;gap:24px;flex-wrap:wrap}.card{padding:12px;background:#26353d}canvas{display:block}button,select{font:inherit;background:#344b57;color:white;padding:8px;border:1px solid #647f8e}.controls{display:flex;gap:14px;align-items:center;flex-wrap:wrap;margin:18px 0}img{max-width:100%;height:auto}</style>
<h1>Veld — coherent sofa reading</h1><p>Tablet draw, reading hold and stow use the same seated body, head, hair and selected helmet. Only the lower forearms, gloves and tablet change. Neutral entry and exit exactly match the south sit-down and rise poses. This candidate keeps the existing twelve-second reading activity; the staged sequence has now passed sofa playback, power/suspension exits and fresh-load checks in both equipment variants.</p>
<div class="controls"><label>Equipment <select id="gear"><option value="bare">Bare</option><option value="helmet">Helmet</option></select></label><button id="play">Pause</button><label>Frame <input id="slot" type="range" min="0" max="13" value="0"></label><span id="status">Loading</span></div><div class="row"><div class="card"><strong>Seated body master</strong><canvas id="master" width="256" height="256"></canvas></div><div class="card"><strong>Reading pose</strong><canvas id="pose" width="256" height="256"></canvas></div></div>
<p>Playback is slowed to one-third speed; the full cycle stops with the tablet stowed.</p><p><a href="paired-contact.png">Source poses and hand close-ups</a> · <a href="read-cycle.gif">Both variants through the full cycle</a> · <a href="../veld-seated-south-coherent-v1/sofa-source-joins.png">Actual controller source joins</a> · <a href="../veld-seated-south-coherent-v1/sofa-native-joins.png">Actual observation sofa joins</a> · <a href="continue-contact.png">Reading before and after Continue</a> &middot; <a href="interrupt-continue-contact.png">Interrupted stow before and after Continue</a> &middot; <a href="HANDOFF.md">Checks and remaining work</a></p><script>const data=DATA;let images={},playing=true,elapsed=0,last=performance.now(),slot=0;const gear=document.querySelector('#gear'),range=document.querySelector('#slot'),play=document.querySelector('#play'),status=document.querySelector('#status');function reset(){elapsed=0;slot=0;range.value=0;playing=true;play.textContent='Pause'}gear.onchange=reset;range.oninput=()=>{slot=Number(range.value);playing=false;play.textContent='Replay'};play.onclick=()=>{if(playing){playing=false;play.textContent='Replay'}else reset()};function load(p){return new Promise((yes,no)=>{const im=new Image();im.onload=()=>yes(im);im.onerror=()=>no(Error(p));im.src=p+'?v=bounded-read-v1'})}
Promise.all(Object.values(data).flat().flatMap(s=>s.frameFiles).filter((v,i,a)=>a.indexOf(v)===i).map(async p=>images[p]=await load(p))).then(()=>{function draw(now){if(playing)elapsed+=(now-last)/3;last=now;const s=data[gear.value][0];if(playing){slot=0;let t=elapsed;while(slot<s.frameFiles.length-1&&t>=s.frameDurationsMs[slot])t-=s.frameDurationsMs[slot++];if(elapsed>=12000){playing=false;play.textContent='Replay'}range.value=slot}for(const [id,im] of [['master',images[s.frameFiles[0]]],['pose',images[s.frameFiles[slot]]]]){let c=document.querySelector('#'+id).getContext('2d');c.clearRect(0,0,256,256);c.drawImage(im,0,0)}status.textContent=`Frame ${slot} / 13`;requestAnimationFrame(draw)}requestAnimationFrame(draw)}).catch(e=>status.textContent='Missing image: '+e.message);</script>'''
(P/'index.html').write_text(page.replace('DATA',json.dumps(data)),encoding='utf-8');print('Paired finite12s reading review/GIF saved; GIF36s slowed timing verified.')
